/* Adapted from Jekyll Theme Chirpy, © 2019 Cotes Chung, MIT license. */
'use strict';

importScripts('./assets/js/data/swconf.js');

const { cacheName, purge, resources, interceptor } = swconf;
const siteCache = `${cacheName}-network`;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    if (!purge) {
      const cache = await caches.open(siteCache);
      await cache.addAll(resources);
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    const obsolete = keys.filter(key => key.startsWith('chirpy-') && (purge || key !== siteCache));
    await Promise.all(obsolete.map(key => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data === 'SKIP_WAITING') event.waitUntil(self.skipWaiting());
});

async function serve(request) {
  if (purge) return fetch(request);

  const url = new URL(request.url);
  const skipCache = interceptor.paths.some(path => url.pathname.startsWith(path))
    || interceptor.urlPrefixes.some(prefix => url.href.startsWith(prefix));
  if (skipCache) return fetch(request);

  const cache = await caches.open(siteCache);
  const document = request.mode === 'navigate';
  if (!document) {
    const cached = await cache.match(request);
    if (cached) return cached;
  }

  try {
    const response = await fetch(request, document ? { cache: 'no-cache' } : undefined);
    if (response.ok || response.type === 'opaque') {
      await cache.put(request, response.clone()).catch(() => {});
    }
    return response;
  } catch (error) {
    if (document) {
      const cached = await cache.match(request);
      if (cached) return cached;
    }
    throw error;
  }
}

self.addEventListener('fetch', event => {
  const { request } = event;
  if (request.method === 'GET' && !request.headers.has('range')) {
    event.respondWith(serve(request));
  }
});
